insert into public.word_formation_families (id,noun,verb,adjective,adverb,meaning_vi,example_pos,example_blank_en,example_vi,source_warning,source_archive_sha256) values (252,'mediation','mediate','mediatory',null,'Hòa giải','noun','The two sides agreed to seek ____ before going to court.','Hai bên đồng ý tìm cách hòa giải trước khi ra tòa.',null,'1bdd47e3c49532930ad4a269ea87e65d126140d133cbfc39388eb2befb574251') on conflict (id) do nothing;
